<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT p.*,b.bill_no,b.total,b.customer_name,u.full_name FROM payments p JOIN bills b ON b.id=p.bill_id JOIN users u ON u.id=p.cashier_id WHERE p.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r)exit('Receipt haipo');?><!doctype html><html lang="sw"><head><meta charset="utf-8"><title>Receipt <?=e($r['receipt_no'])?></title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="receipt"><div class="text-center"><h2>RESTAURANT</h2><h3>PAYMENT RECEIPT</h3><p>Receipt No: <b><?=e($r['receipt_no'])?></b><br>Bill No: <?=e($r['bill_no'])?><br><?=e($r['paid_at'])?></p></div><hr><p>Mteja: <?=e($r['customer_name']?:'Walk-in')?></p><h2 class="text-center">PAID: TSh <?=number_format($r['amount'],2)?></h2><p>Payment Method: <?=e($r['method'])?><br>Reference: <?=e($r['reference_no']?:'-')?><br>Cashier: <?=e($r['full_name'])?></p><p>Bill Total: TSh <?=number_format($r['total'],2)?></p><div class="actions no-print"><button onclick="window.print()">Print Receipt</button><a class="btn gray" href="../payments/index.php">Back</a></div></div></body></html>
